import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be a dense array');
  }

  const entries = [];
  const ids = new Set();
  // Validate every entry before making any budget decisions.
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      throw new Error('sections must not contain missing slots');
    }
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error(`Invalid section at index ${index}`);
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 ||
        typeof text !== 'string' ||
        !Number.isSafeInteger(priority) || priority < 0 ||
        typeof required !== 'boolean') {
      throw new Error(`Invalid section fields at index ${index}`);
    }
    if (ids.has(id)) throw new Error(`Duplicate section ID: ${JSON.stringify(id)}`);
    ids.add(id);
    const frame = '### ' + JSON.stringify(id) + '\n' + text + '\n';
    entries.push({ id, priority, required, index, frame, cost: Buffer.byteLength(frame, 'utf8') });
  }

  let remaining = maxBytes;
  const selected = new Set();
  const frames = [];
  const included = [];
  const include = (entry) => {
    remaining -= entry.cost;
    selected.add(entry.index);
    frames.push(entry.frame);
    included.push(entry.id);
  };
  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > remaining) throw new Error('Required sections exceed maxBytes');
    include(entry);
  }
  const optional = entries.filter((entry) => !entry.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) include(entry);
  }

  return {
    text: frames.join(''),
    bytes: maxBytes - remaining,
    included,
    omitted: entries.filter((entry) => !entry.required && !selected.has(entry.index))
      .map((entry) => entry.id),
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('Input must be an object containing sections and maxBytes');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

