import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) => ({ id, text, priority, required });
const frame = ({ id, text }) => '### ' + JSON.stringify(id) + '\n' + text + '\n';
const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
const run = (...args) => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });

test('preserves exact framing, unusual IDs, and frozen inputs', () => {
  const entries = Object.freeze(['__proto__', 'A', 'a', ' \n\0雪"\\'].map((id) =>
    Object.freeze(section(id, ' \r\n😀\0\ud800 ', 0, true))));
  const text = entries.map(frame).join('');
  const bytes = Buffer.byteLength(text, 'utf8');
  assert.deepEqual(packContext(entries, bytes), {
    text, bytes, included: entries.map((entry) => entry.id), omitted: [],
  });
  assert.throws(() => packContext(entries, bytes - 1), Error);
  assert.equal(packContext(entries, Number.MAX_SAFE_INTEGER).bytes, bytes);
});

test('required input order, optional priority ties, and omitted input order', () => {
  const entries = [
    section('low', 'x'.repeat(100), 0), section('first', '', 3),
    section('r1', '', 0, true), section('high', 'x'.repeat(100), 100),
    section('second', '', 3), section('r2', '', 100, true), section('last', '', 1),
  ];
  const included = [entries[2], entries[5], entries[1], entries[4]];
  const text = included.map(frame).join('');
  assert.deepEqual(packContext(entries, Buffer.byteLength(text)), {
    text, bytes: Buffer.byteLength(text), included: included.map((entry) => entry.id),
    omitted: ['low', 'high', 'last'],
  });
});

test('rejects invalid inputs even with zero budget', () => {
  for (const budget of [-1, 0.1, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '0', null, undefined, 0n]) {
    assert.throws(() => packContext([], budget), Error);
  }
  for (const entries of [null, {}, 'x', [null], [[]], [1], new Array(1)]) {
    assert.throws(() => packContext(entries, 0), Error);
  }
  for (const [key, values] of Object.entries({
    id: ['', null, 1], text: [null, 1],
    priority: [-1, 0.5, Infinity, NaN, Number.MAX_SAFE_INTEGER + 1, '1'],
    required: [0, 1, 'false', null],
  })) {
    for (const value of [...values, undefined]) {
      assert.throws(() => packContext([section('ok'), { ...section('bad'), [key]: value }], 0), Error);
    }
    const missing = section('bad');
    delete missing[key];
    assert.throws(() => packContext([missing], 0), Error);
  }
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
});

